<?php
require_once __DIR__.'/../auth_check.php';
AccessManager::requirePageAccess();
require_once __DIR__.'/../services/RhFinancialPointService.php';
require_once __DIR__.'/../services/RhFinancialSchema.php';
$pdo=Database::getConnection();$service=new RhFinancialPointService($pdo);$userId=(int)($_SESSION['user_id'] ?? 0);
$_SESSION['rh_financial_csrf']??=bin2hex(random_bytes(32));$csrf=$_SESSION['rh_financial_csrf'];
$kind=(string)($_GET['kind'] ?? 'advance');if(!isset(RhFinancialPointPolicy::KINDS[$kind]))$kind='advance';
$period=(string)($_GET['period'] ?? date('Y-m'));$error='';$message='';$point=null;$settings=[];$candidates=[];$points=[];$budgetOptions=[];$dgOptions=[];$serviceOptions=[];
$message=is_string($_SESSION['rh_financial_notice'] ?? null)?$_SESSION['rh_financial_notice']:'';unset($_SESSION['rh_financial_notice']);
$schemaReady=false;$missingTables=[];
$canRh=AccessManager::hasPermission('acces_rh')||AccessManager::hasPermission('acces_admin');$canAdmin=AccessManager::hasPermission('acces_admin');
try {
    // DG configuration must not depend on candidate payroll/budget loading.
    if($canAdmin)$dgOptions=$service->directionCandidates($userId);
    $missingTables=RhFinancialSchema::missing($pdo,false);$schemaReady=!$missingTables;
    if(!$schemaReady)throw new DomainException('Le module financier RH doit être installé avant de pouvoir enregistrer le DG et préparer les points.');
    $settings=$service->settings();
    if($_SERVER['REQUEST_METHOD']==='POST') {
        if(!hash_equals($csrf,(string)($_POST['_csrf'] ?? '')))throw new DomainException('Session expirée. Rechargez la page.');
        $action=(string)($_POST['action'] ?? '');$id=(int)($_POST['id'] ?? 0);$revision=(int)($_POST['revision'] ?? 0);
        if($action==='configure'){$service->configure($userId,(int)$_POST['dg_user_id'],(string)$_POST['dg_phone']);$message='DG et numéro WhatsApp enregistrés.';}
        elseif($action==='create'){
            $selection=explode(':',(string)($_POST['budget_line'] ?? ''));$budget=['chantier_id'=>(int)($selection[0] ?? 0),'ligne_debourse_id'=>(int)($selection[1] ?? 0),'service_id'=>(int)($_POST['service_id'] ?? 0),'date'=>(string)$_POST['date'],'mode_paiement'=>(string)$_POST['mode_paiement']];
            $id=$service->create((string)$_POST['kind'],(string)$_POST['period'],(array)($_POST['ids'] ?? []),$userId,$budget);
            header('Location: points_financiers_rh.php?id='.$id);exit;
        }
        elseif($action==='discard'){$service->discard($id,$revision,$userId);$message='Brouillon annulé. Les lignes sont de nouveau disponibles.';}
        elseif($action==='stop'){$service->stop($id,$revision,$userId,(string)($_POST['signature_method'] ?? 'passkey'),(string)($_POST['rh_manual_signature'] ?? ''));$message='Point arrêté et signé par les RH. Envoyez l’invitation WhatsApp au DG.';}
        elseif(in_array($action,['notify','resend'],true)){$service->notify($id,$revision,$userId,$action==='resend');$_SESSION['rh_financial_notice']='Invitation WhatsApp acceptée par Twilio. Le nouveau lien est valable 24 heures ; sa réception reste à confirmer.';header('Location: points_financiers_rh.php?id='.$id);exit;}
        elseif($action==='reopen'){$service->reopen($id,$revision,$userId,(string)$_POST['reason']);$message='Nouvelle version ouverte. La personne ayant arrêté le point doit signer de nouveau, puis envoyer une nouvelle invitation au DG.';}
        else throw new DomainException('Action inconnue.');
    }
    $settings=$service->settings();$points=$service->list();
    $id=(int)($_GET['id'] ?? $_POST['id'] ?? 0);if($id)$point=$service->get($id);
    if(!$point && $canRh)$candidates=$service->candidates($kind,$period);
    if($canRh)$budgetOptions=$pdo->query("SELECT DISTINCT c.id chantier_id,c.code,l.id,l.designation FROM ligne_debourse_banamur l JOIN debourse_banamur d ON d.id=l.debourse_id JOIN chantier_banamur c ON (c.devis_id=d.devis_id OR EXISTS(SELECT 1 FROM devis_chantier_links cl WHERE cl.devis_id=d.devis_id AND cl.chantier_id=c.id)) WHERE c.archived_at IS NULL ORDER BY c.code,l.designation")->fetchAll(PDO::FETCH_ASSOC);
    if($canRh)$serviceOptions=$pdo->query('SELECT id_service,lib_service FROM service ORDER BY lib_service')->fetchAll(PDO::FETCH_ASSOC);
}catch(PDOException $e){error_log('RH points: '.$e->getMessage());$error='Chargement incomplet. Vérifiez l’installation RH et consultez le journal PHP du serveur.';}catch(Throwable $e){$error=$e->getMessage();}
$h=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$money=static fn($v)=>number_format((float)$v,0,',',' ').' FCFA';
$pageTitle='Points financiers RH';$activeMenu='rh';require_once __DIR__.'/../decaissement/includes/header.php';require_once __DIR__.'/../decaissement/includes/navbar.php';
?>
