<form method="post" class="rh-form-grid"><input type="hidden" name="_csrf" value="<?=$h($csrf)?>"><input type="hidden" name="action" value="configure"><label for="rh-dg">Compte du DG<select id="rh-dg" data-rh-search-select name="dg_user_id" required <?=$schemaReady?'':'disabled'?>><option value="">Sélectionnez le signataire</option><?php foreach($dgOptions as $dg):?><option value="<?=(int)$dg['id']?>" <?=(int)($settings['dg_user_id'] ?? 0)===(int)$dg['id']?'selected':''?>><?=$h(trim(($dg['prenom']??'').' '.($dg['nom']??''))?:'Compte Direction')?> · <?=$h($dg['email'])?></option><?php endforeach?></select><small>Comptes actifs disposant de l’accès Direction.</small></label><label for="rh-dg-phone">Numéro WhatsApp du DG<input id="rh-dg-phone" type="tel" inputmode="tel" autocomplete="tel" name="dg_phone" value="<?=$h($settings['dg_phone'] ?? '')?>" placeholder="+225 07 00 00 00 00" required <?=$schemaReady?'':'disabled'?>><small>Format international avec indicatif pays.</small></label><div class="rh-form-action"><button <?=$schemaReady&&$dgOptions?'':'disabled'?>>Enregistrer le signataire</button></div></form>
<?php if(!$dgOptions):?><p class="rh-banner">Aucun compte Direction actif disponible. Vérifiez l’accès Direction du compte DG dans la gestion des utilisateurs.</p><?php endif?>
<div class="rh-configuration-footer"><div><b>Notifications WhatsApp</b><p>Créez les modèles d’avances et de prêts, puis suivez leur validation Meta.</p></div><a class="rh-btn rh-btn-outline" href="suivi_templates_whatsapp_rh.php">Suivre les modèles WhatsApp</a></div></section><?php endif?>
<?php if($schemaReady):?><div class="rh-summary-grid"><article><span>En préparation</span><strong><?=count(array_filter($points,static fn($p)=>$p['status']==='draft'))?></strong><small>Points à arrêter et signer par les RH</small></article><article><span>En attente du DG</span><strong><?=count(array_filter($points,static fn($p)=>$p['status']==='rh_signed'))?></strong><small>Points transmis pour décision et signature</small></article><article><span>Validés par le DG</span><strong><?=count(array_filter($points,static fn($p)=>$p['status']==='dg_signed'))?></strong><small>Récapitulatifs définitifs et FEB associées</small></article></div>
<?php if($point):$revision=(int)$point['revision'];?><section><?php $rhPointSummary=$point;require __DIR__.'/includes/financial_point_summary.php';?><div class="rh-scroll"><table><thead><tr><th>Collaborateur</th><th>Demande</th><th>Demandé</th><th>Retenu</th><th>Décision / report</th></tr></thead><tbody><?php foreach($point['snapshot']['lines'] as $line):?><tr><td><?=$h($line['name'])?></td><td><?=$h($line['label'])?></td><td><?=$money($line['initial_amount'])?></td><td><?=$money($line['decision']==='approved'?$line['amount']:0)?></td><td><?=$h((['approved'=>'Approuvée','rejected'=>'Refusée','cancelled'=>'Annulée','deferred'=>'Reportée'][$line['decision']] ?? $line['decision']).' '.$line['deferred_until'].' '.$line['note'])?></td></tr><?php endforeach?></tbody></table></div>
<?php if($canRh):?>
<?php if($point['status']==='draft' && (int)$point['stopped_by']===$userId):?><form method="post" data-passkey-signature data-passkey-endpoint-base="../request" data-passkey-context="rh_financial:<?=(int)$point['id']?>:<?=$revision?>:rh"><input type="hidden" name="_csrf" value="<?=$h($csrf)?>"><input type="hidden" name="action" value="stop"><input type="hidden" name="id" value="<?=(int)$point['id']?>"><input type="hidden" name="revision" value="<?=$revision?>"><input type="hidden" name="signature_method" value="passkey"><button>Arrêter et signer avec Passkey</button></form>
<form method="post" data-rh-manual-signature>
<input type="hidden" name="_csrf" value="<?=$h($csrf)?>"><input type="hidden" name="action" value="stop"><input type="hidden" name="id" value="<?=(int)$point['id']?>"><input type="hidden" name="revision" value="<?=$revision?>"><input type="hidden" name="signature_method" value="manual"><input type="hidden" name="rh_manual_signature" value="">
<h3>Signature manuscrite RH</h3><p>Dessinez votre signature à la souris ou au doigt pour arrêter cette version du point.</p>
